608	async function poll(fn, { timeout = 6000, interval = 80, label = "" } = {}) {
609	  const deadline = Date.now() + timeout;
610	  let lastErr;
611	  while (Date.now() < deadline) {
612	    try {
613	      const v = await fn();
614	      if (v) return v;
615	    } catch (e) { lastErr = e; }
616	    await sleep(interval);
617	  }
618	  throw new Error(`等待页面状态超时${label ? "（" + label + "）" : ""}${lastErr ? ": " + lastErr.message : ""}`);
619	}
