83	
84	// load 读取并解析全部记录。读不到、JSON 损坏、结构异常，或任一场地的名称、
85	// 容量、时区、开放时段不满足新增功能已经公开的有效性规则，都返回错误，调用
86	// 方必须按 500 处理。绝不能把错误数据当作空列表覆盖，也不能跳过异常场地只
87	// 返回剩余记录；异常记录前后即使都有正常场地，整次读取也必须失败。
88	func (s *store) load() ([]Venue, error) {
89		raw, err := os.ReadFile(s.path)
90		if err != nil {
91			return nil, err
92		}
93		// 用 UseNumber 做通用解码，让 capacity 等数字保留原始十进制文本
94		// （json.Number），与新增入口一致：既不会把带小数的值静默舍入成整数，
95		// 也能逐位识别超过 JavaScript 安全整数范围、但仍在服务端支持范围内的
96		// 容量。直接解码到具体结构体会把缺失/null 的名称、容量、时区填成零值，
97		// 从而漏掉存量数据里的异常，因此这里先解码成 map 再逐字段严格校验。
98		decoder := json.NewDecoder(bytes.NewReader(raw))
99		decoder.UseNumber()
100		var records []map[string]any
101		if err := decoder.Decode(&records); err != nil {
102			return nil, fmt.Errorf("venues data is corrupted: %w", err)
103		}
104		// 拒绝数组之后的多余 JSON 内容（等价于此前 json.Unmarshal 的单值约束）。
105		var extra json.RawMessage
106		if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
107			return nil, fmt.Errorf("venues data is corrupted: unexpected content after venue array")
108		}
109	
110		venues := make([]Venue, 0, len(records))
111		for i, rec := range records {
112			// 数组中的 null（解码为 nil map）或任何非对象条目都是数据异常，
113			// 不能变成名称为空、容量为零的场地。非对象条目在解码阶段已报错，
114			// 这里拦的是 null。
115			if rec == nil {
116				return nil, fmt.Errorf("venues data is corrupted at venue index %d: entry is null", i)
117			}
118			venue, err := decodeStoredVenue(rec)
119			if err != nil {
120				return nil, fmt.Errorf("venues data is corrupted at venue index %d: %w", i, err)
121			}
122			venues = append(venues, venue)
123		}
124		return venues, nil
125	}
126	
127	// decodeStoredVenue 对一条已保存记录逐字段做严格校验，规则与 buildVenue 在
128	// 新增请求上公开的规则完全一致。任何不满足都返回错误（由 load 按数据损坏、
129	// HTTP 500 处理），绝不把错误类型或缺失值转换成合法零值。
130	func decodeStoredVenue(rec map[string]any) (Venue, error) {
131		// 标识不是本次校验重点，但类型错误仍属于结构异常：缺失/null 与历史行为
132		// 一样按空串读取，其它非字符串类型直接判损坏。
133		id, err := optionalStringField(rec, "id")
134		if err != nil {
135			return Venue{}, err
136		}
137	
138		name, err := storedName(rec)
139		if err != nil {
140			return Venue{}, err
141		}
142	
143		capacity, err := storedCapacity(rec)
144		if err != nil {
145			return Venue{}, err
146		}
