		if err := validateHours(hours); err != nil {
			return Venue{}, err
		}
	}

	return Venue{
		ID:          id,
		Name:        name,
		Capacity:    capacity,
		Timezone:    timezone,
		WeeklyHours: hours,
	}, nil
}

